RADIO_SELECTED = u'\u25C9'      # ◉
PROGRESS_CHARS = [u'\u2591', u'\u2592', u'\u2593', u'\u2588']  # ░ ▒ ▓ █
SLIDER_LEFT = u'\u25C0'         # ◀
SLIDER_RIGHT = u'\u25B6'        # ▶
SLIDER_KNOB = u'\u25CF'         # ●
MENU_ARROW = u'\u25B6'          # ▶

# Simulate LCD connection
def connect_lcd(port):
    # Placeholder for actual LCD connection logic
    return True

# Custom ProgressBar widget
class CustomProgressBar(urwid.Widget):
    def __init__(self, current, done, width=10):
        self.current = current
        self.done = done
        self.width = width

    def set_completion(self, value):
        self.current = value
        self._invalidate()

    def render(self, size, focus=False):
        width = self.width
        percent = float(self.current) / self.done if self.done else 0
        full_blocks = int(percent * width)
        partial_block = int((percent * width - full_blocks) * (len(PROGRESS_CHARS)-1))
        text = ''
        for i in range(width):
            if i < full_blocks:
                text += PROGRESS_CHARS[-1]
            elif i == full_blocks and percent > 0:
                text += PROGRESS_CHARS[partial_block]
            else:
                text += PROGRESS_CHARS[0]
        return urwid.Text(text).render((width,))

# Custom Slider widget
class CustomSlider(urwid.WidgetWrap):
    def __init__(self, min_value, max_value, value, width=12, on_change=None):
        self.min = min_value
        self.max = max_value
        self.value = value
        self.width = width
        self.on_change = on_change
        self._update_widget()
        super().__init__(self.widget)

    def _update_widget(self):
        pos = int((self.value - self.min) / (self.max - self.min) * (self.width-3))
        slider = SLIDER_LEFT
        for i in range(self.width-2):
            if i == pos:
                slider += SLIDER_KNOB
            else:
                slider += u'-'
        slider += SLIDER_RIGHT
        self.widget = urwid.Text(slider)

    def keypress(self, size, key):
        if key in ('left', 'h'):
            if self.value > self.min:
                self.value -= 1
                if self.on_change:
                    self.on_change(self.value)
                self._update_widget()
                self._w = self.widget
        elif key in ('right', 'l'):
            if self.value < self.max:
                self.value += 1
                if self.on_change:
                    self.on_change(self.value)
                self._update_widget()
                self._w = self.widget
        else:
            return key

# Custom Checkbox widget
class CustomCheckBox(urwid.CheckBox):
    def get_label(self):
        return self.label

    def get_display_text(self):
        return (CHECKBOX_CHECKED if self.state else CHECKBOX_UNCHECKED) + ' ' + self.label

    def render(self, size, focus=False):
        return urwid.Text(self.get_display_text()).render(size, focus)

